{"content":"import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { loadConfig } from "../config-loader.js";

let dir;

before(async () => {
  dir = await mkdtemp(join(tmpdir(), "config-loader-"));
});

after(async () => {
  await rm(dir, { recursive: true, force: true });
});

async function writeConfig(name, content) {
  const file = join(dir, name);
  await writeFile(file, content);
  return file;
}

test("user values take precedence over defaults", async () => {
  const file = await writeConfig(
    "flat.json",
    JSON.stringify({ port: 8080, host: "example.com" })
  );
  const config = await loadConfig(file, { port: 3000, debug: true });
  assert.deepEqual(config, { port: 8080, host: "example.com", debug: true });
});

test("nested objects are deep merged with user precedence", async () => {
  const file = await writeConfig(
    "nested.json",
    JSON.stringify({ db: { host: "prod-db" } })
  );
  const config = await loadConfig(file, {
    db: { host: "localhost", port: 5432 },
    retries: 3,
  });
  assert.deepEqual(config, {
    db: { host: "prod-db", port: 5432 },
    retries: 3,
  });
});

test("arrays from user config replace defaults", async () => {
  const file = await writeConfig(
    "arrays.json",
    JSON.stringify({ tags: ["prod"] })
  );
  const config = await loadConfig(file, { tags: ["dev", "test"] });
  assert.deepEqual(config, { tags: ["prod"] });
});

test("defaults object is not mutated", async () => {
  const file = await writeConfig(
    "nomutate.json",
    JSON.stringify({ port: 9000 })
  );
  const defaults = { port: 3000, db: { host: "localhost" } };
  await loadConfig(file, defaults);
  assert.deepEqual(defaults, { port: 3000, db: { host: "localhost" } });
});

test("invalid JSON is rejected", async () => {
  const file = await writeConfig("bad.json", "{not json");
  await assert.rejects(() => loadConfig(file, {}));
});

test("non-object config is rejected", async () => {
  const file = await writeConfig("nonobject.json", '"just a string"');
  await assert.rejects(
    () => loadConfig(file, {}),
    { name: "TypeError" }
  );
});
","path":"test/config-loader.test.js"}

